import{_ as d,o as r,c as a,ae as o}from"./chunks/framework.RRduUuAx.js";const c=JSON.parse('{"title":"架构师-备考 背诵记忆-核心速记口诀","description":"","frontmatter":{"title":"架构师-备考 背诵记忆-核心速记口诀"},"headers":[],"relativePath":"核心速记口诀/index.md","filePath":"核心速记口诀/index.md"}'),e={name:"核心速记口诀/index.md"};function n(s,t,h,l,i,g){return r(),a("div",null,[...t[0]||(t[0]=[o('<h2 id="知识点速记口诀" tabindex="-1">知识点速记口诀 <a class="header-anchor" href="#知识点速记口诀" aria-label="Permalink to &quot;知识点速记口诀&quot;">​</a></h2><table tabindex="0"><thead><tr><th>知识点</th><th>口诀</th><th>展开</th></tr></thead><tbody><tr><td><strong>质量属性6要素</strong></td><td>刺刺制环响响</td><td>刺激源、刺激、制品、环境、响应、响应度量</td></tr><tr><td><strong>软件质量6属性</strong></td><td>用改性安测易</td><td>可用性、可修改性、性能、安全性、可测试性、易用性</td></tr><tr><td><strong>DFD 4种元素</strong></td><td>数加实存</td><td>数据流、加工、实体、存储</td></tr><tr><td><strong>高质量DFD 3原则</strong></td><td>复接数</td><td>复杂性最小化、接口最小化、数据流一致性</td></tr><tr><td><strong>用例间关系</strong></td><td>包扩泛</td><td>包含、扩展、泛化</td></tr><tr><td><strong>类之间关系</strong></td><td>关聚组依泛实</td><td>关联、聚合、组合、依赖、泛化、实现</td></tr><tr><td><strong>可靠性子特性</strong></td><td>成容易依</td><td>成熟性、容错性、易恢复性、依从性</td></tr><tr><td><strong>检错技术4要素</strong></td><td>对延实处</td><td>检测对象、检测延时、实现方式、处理方式</td></tr><tr><td><strong>可维护性6子度量</strong></td><td>圈扇模模紧松内</td><td>圈复杂度CCN、扇入扇出度FFC、模块间耦合度CBO、模块响应RFC、紧内聚度TCC、松内聚度LCC</td></tr><tr><td><strong>ABSD 6步骤</strong></td><td>需求设计文档化，复审实现和演化</td><td>架构需求→设计→文档化→复审→实现→演化</td></tr><tr><td><strong>创建型模式</strong></td><td>单工抽建原</td><td>单例、工厂方法、抽象工厂、建造者、原型</td></tr><tr><td><strong>结构型模式</strong></td><td>适组代享装桥外</td><td>适配器、组合、代理、享元、装饰、桥接、外观</td></tr><tr><td><strong>架构演化6步骤</strong></td><td>归演变更组评</td><td>需求变化归类→制订计划→构件变动→更新相互作用→组装测试→技术评审</td></tr><tr><td><strong>非功能需求分类</strong></td><td>性安操文</td><td>性能、安全、操作、文化</td></tr><tr><td><strong>软件设计4部分</strong></td><td>架数接过</td><td>架构设计、数据设计、接口设计、过程设计</td></tr><tr><td><strong>构件获取4方法</strong></td><td>现遗市开</td><td>现有构件、遗留工程、市场购买、新开发</td></tr><tr><td><strong>EJB 3种Bean</strong></td><td>会实消</td><td>会话Bean、实体Bean、消息驱动Bean</td></tr><tr><td><strong>应用服务4层</strong></td><td>表中访数</td><td>表现层、中间层、访问层、数据层</td></tr><tr><td><strong>ESB主要功能</strong></td><td>服传消消消安监</td><td>服务位置透明、传输协议转换、消息格式转换、消息路由、消息增强、安全、监控管理</td></tr><tr><td><strong>基础设施支持</strong></td><td>构互公</td><td>构件管理、互操作、公共服务</td></tr><tr><td><strong>数据库主从优点</strong></td><td>性扩用负安</td><td>性能、可扩展、可用性、负载均衡、数据安全</td></tr><tr><td><strong>NoSQL 4类</strong></td><td>键列文图</td><td>键值型、列存储、文档型、图数据库</td></tr><tr><td><strong>NoSQL 4层框架</strong></td><td>持分逻接</td><td>数据持久层、数据分布层、数据逻辑模型层、接口层</td></tr><tr><td><strong>NoSQL优势</strong></td><td>灵高拓集</td><td>灵活多格式、高吞吐量、高水平扩展、集群避免单点故障</td></tr><tr><td><strong>反规范化4技术</strong></td><td>增增表表</td><td>增加冗余列、增加派生列、表水平分割、表垂直分割</td></tr><tr><td><strong>嵌入式系统5层</strong></td><td>硬抽操中应</td><td>硬件层、抽象层、操作系统层、中间件层、应用层</td></tr><tr><td><strong>嵌入式系统特点</strong></td><td>裁移实资靠，定稳交确固</td><td>可剪裁、可移植、强实时、资源受限、高可靠、强定制、强稳定、强交互、强确定、可固化</td></tr><tr><td><strong>实时系统特性</strong></td><td>时可高交多约短</td><td>时间约束性、可预测性、高可靠性、交互作用性、多任务类型、约束复杂性、短暂超载</td></tr><tr><td><strong>实时系统调度</strong></td><td>分轮抢</td><td>时间分片式、轮流查询式、优先抢占式</td></tr><tr><td><strong>开放架构4特点</strong></td><td>移互裁易</td><td>可移植性、可互操作性、可剪裁性、易获得性</td></tr><tr><td><strong>抵御SQL注入</strong></td><td>正过检加存漏</td><td>正则表达式、参数化过滤、检查合法性、加密处理、存储过程、漏洞扫描</td></tr><tr><td><strong>访问控制3模型</strong></td><td>自强基角</td><td>自主DAC、强制MAC、基于角色RBAC</td></tr><tr><td><strong>信息系统安全6层</strong></td><td>物通网操应管</td><td>物理、通信链路、网络、操作系统、应用、管理</td></tr><tr><td><strong>认证方式</strong></td><td>用口令牌生物</td><td>用户名口令、令牌认证、生物识别</td></tr><tr><td><strong>CPS分层</strong></td><td>感网控</td><td>感知层、网络层、控制层</td></tr></tbody></table><hr><h2 id="质量属性速查" tabindex="-1">质量属性速查 <a class="header-anchor" href="#质量属性速查" aria-label="Permalink to &quot;质量属性速查&quot;">​</a></h2><table tabindex="0"><thead><tr><th>属性</th><th>关注点</th><th>策略</th></tr></thead><tbody><tr><td><strong>可用性</strong></td><td>故障可能性和恢复能力</td><td>ping/echo、心跳、事务、主动冗余</td></tr><tr><td><strong>可修改性</strong></td><td>变更难易程度</td><td>抽象接口、信息隐藏、延迟绑定、运行时注册</td></tr><tr><td><strong>性能</strong></td><td>事件响应时间</td><td>增加资源、引入并发、资源调度、优先级队列</td></tr><tr><td><strong>安全性</strong></td><td>合法用户/阻止非法</td><td>身份验证、限制访问、入侵检测、追踪审计</td></tr><tr><td><strong>可测试性</strong></td><td>发现错误能力</td><td>记录/回放、接口与实现分离、内部监视</td></tr><tr><td><strong>易用性</strong></td><td>用户完成任务容易程度</td><td>维护用户信息、系统信息、支持主动操作</td></tr></tbody></table><h3 id="错误-缺陷-故障-失效关系" tabindex="-1">错误/缺陷/故障/失效关系 <a class="header-anchor" href="#错误-缺陷-故障-失效关系" aria-label="Permalink to &quot;错误/缺陷/故障/失效关系&quot;">​</a></h3><p>软件错误（人为）→ 软件缺陷（偏差）→ 软件故障（内部状态）→ 软件失效（外部行为）。</p><h3 id="敏感点-vs-权衡点-vs-风险点" tabindex="-1">敏感点 vs 权衡点 vs 风险点 <a class="header-anchor" href="#敏感点-vs-权衡点-vs-风险点" aria-label="Permalink to &quot;敏感点 vs 权衡点 vs 风险点&quot;">​</a></h3><table tabindex="0"><thead><tr><th>概念</th><th>定义</th></tr></thead><tbody><tr><td><strong>敏感点</strong></td><td>为实现特定质量属性，构件具有的特性</td></tr><tr><td><strong>权衡点</strong></td><td>影响<strong>多个</strong>质量属性的敏感点</td></tr><tr><td><strong>风险点</strong></td><td>架构设计中潜在问题决策带来的隐患</td></tr><tr><td><strong>非风险点</strong></td><td>确认不会造成威胁的点</td></tr></tbody></table><hr><h2 id="可靠性关键指标" tabindex="-1">可靠性关键指标 <a class="header-anchor" href="#可靠性关键指标" aria-label="Permalink to &quot;可靠性关键指标&quot;">​</a></h2><table tabindex="0"><thead><tr><th>指标</th><th>含义</th></tr></thead><tbody><tr><td><strong>MTTF</strong></td><td>平均故障发生时间</td></tr><tr><td><strong>MTTD</strong></td><td>平均故障检测时间</td></tr><tr><td><strong>MTTR</strong></td><td>平均修复时间</td></tr><tr><td><strong>MTBF</strong></td><td>平均故障间隔时间</td></tr><tr><td><strong>MTBR</strong></td><td>平均修复间隔时间</td></tr></tbody></table><p><strong>提高可靠性4类技术</strong>：容错技术（恢复块+N版本+冗余）、检错技术（4要素）、降低复杂度、系统配置（双机热备/互备/双工+集群）。</p><h3 id="ping-echo-vs-心跳" tabindex="-1">ping/echo vs 心跳 <a class="header-anchor" href="#ping-echo-vs-心跳" aria-label="Permalink to &quot;ping/echo vs 心跳&quot;">​</a></h3><p>心跳更优：资源消耗少（主动发短消息）、网络负载低（频率低）、故障检测快（立即察觉失联）。</p><hr><h2 id="架构风格补充" tabindex="-1">架构风格补充 <a class="header-anchor" href="#架构风格补充" aria-label="Permalink to &quot;架构风格补充&quot;">​</a></h2><h3 id="dfd-vs-流程图区别" tabindex="-1">DFD vs 流程图区别 <a class="header-anchor" href="#dfd-vs-流程图区别" aria-label="Permalink to &quot;DFD vs 流程图区别&quot;">​</a></h3><table tabindex="0"><thead><tr><th>对比</th><th>DFD</th><th>流程图</th></tr></thead><tbody><tr><td>处理</td><td>可并行</td><td>单时间点单处理</td></tr><tr><td>展现</td><td><strong>数据流</strong></td><td><strong>控制流</strong></td></tr><tr><td>计时</td><td>不同标准</td><td>一致标准</td></tr><tr><td>适用阶段</td><td>逻辑建模</td><td>物理建模</td></tr></tbody></table><h3 id="数据流图错误分类" tabindex="-1">数据流图错误分类 <a class="header-anchor" href="#数据流图错误分类" aria-label="Permalink to &quot;数据流图错误分类&quot;">​</a></h3><ul><li><strong>逻辑错误</strong>：黑洞（无输出）、灰洞（输入不足以产生输出）、无输入</li><li><strong>语法错误</strong>：数据存储不完整、外部实体间未经加工数据流</li></ul><h3 id="状态图-vs-活动图" tabindex="-1">状态图 vs 活动图 <a class="header-anchor" href="#状态图-vs-活动图" aria-label="Permalink to &quot;状态图 vs 活动图&quot;">​</a></h3><p>状态图侧重行为<strong>结果</strong>（不可并发），活动图侧重行为<strong>动作</strong>（可描述并发）。</p><hr><h2 id="架构相关补充" tabindex="-1">架构相关补充 <a class="header-anchor" href="#架构相关补充" aria-label="Permalink to &quot;架构相关补充&quot;">​</a></h2><h3 id="absd-三基础-六步骤" tabindex="-1">ABSD 三基础 + 六步骤 <a class="header-anchor" href="#absd-三基础-六步骤" aria-label="Permalink to &quot;ABSD 三基础 + 六步骤&quot;">​</a></h3><p>三基础：功能分解 + 架构风格选择 + 软件模板使用。</p><blockquote><p>ABSD 是架构驱动的，需求未完成即可开始设计，递归迭代。</p></blockquote><h3 id="架构定义" tabindex="-1">架构定义 <a class="header-anchor" href="#架构定义" aria-label="Permalink to &quot;架构定义&quot;">​</a></h3><p>SA = {组件、连接件、约束}。组件=计算元素/数据存储；连接件=交互关系/通信机制；约束=拓扑关系/配置。</p><h3 id="soa-协议速记" tabindex="-1">SOA 协议速记 <a class="header-anchor" href="#soa-协议速记" aria-label="Permalink to &quot;SOA 协议速记&quot;">​</a></h3><table tabindex="0"><thead><tr><th>协议</th><th>作用</th></tr></thead><tbody><tr><td>UDDI</td><td>统一描述、发现和集成</td></tr><tr><td>WSDL</td><td>描述Web服务和通信方式（XML）</td></tr><tr><td>SOAP</td><td>信息交换协议（基于XML）</td></tr><tr><td>REST</td><td>资源通过URI标识，标准化接口</td></tr><tr><td>BPEL</td><td>组合编排Web服务→复合服务</td></tr></tbody></table><h3 id="mvc-三层" tabindex="-1">MVC 三层 <a class="header-anchor" href="#mvc-三层" aria-label="Permalink to &quot;MVC 三层&quot;">​</a></h3><p>视图（用户界面）→ 控制器（接受输入调用模型）→ 模型（业务数据+逻辑）。</p><h3 id="微服务优缺点" tabindex="-1">微服务优缺点 <a class="header-anchor" href="#微服务优缺点" aria-label="Permalink to &quot;微服务优缺点&quot;">​</a></h3><p>优点：解耦、独立开发/测试/部署、技术灵活、容错隔离、松耦合易扩展。缺点：数据一致性更复杂、测试复杂性、运维复杂性。</p><h3 id="负载均衡" tabindex="-1">负载均衡 <a class="header-anchor" href="#负载均衡" aria-label="Permalink to &quot;负载均衡&quot;">​</a></h3><p><strong>基于DNS</strong>：实现简单成本低，不能区分服务器差异和运行状态。<strong>基于反向代理</strong>：可按性能差异和实时负载动态分配，屏蔽真实服务器防攻击，可引入缓存。</p><hr><h2 id="数据库补充" tabindex="-1">数据库补充 <a class="header-anchor" href="#数据库补充" aria-label="Permalink to &quot;数据库补充&quot;">​</a></h2><h3 id="orm-对比" tabindex="-1">ORM 对比 <a class="header-anchor" href="#orm-对比" aria-label="Permalink to &quot;ORM 对比&quot;">​</a></h3><table tabindex="0"><thead><tr><th>对比</th><th>直接SQL</th><th>ORM</th></tr></thead><tbody><tr><td>优点</td><td>性能好、处理复杂查询</td><td>降低学习成本、减少代码量</td></tr><tr><td>缺点</td><td>需懂SQL、维护困难</td><td>复杂查询困难、性能较差</td></tr></tbody></table><h3 id="分布式存储-crud" tabindex="-1">分布式存储 CRUD <a class="header-anchor" href="#分布式存储-crud" aria-label="Permalink to &quot;分布式存储 CRUD&quot;">​</a></h3><p>读：先缓存→未命中查库→加载缓存返回。增：延迟加载写库。改：更改库+缓存标记失效。删：删除库+缓存标记失效。</p><h3 id="集中式-vs-分布式" tabindex="-1">集中式 vs 分布式 <a class="header-anchor" href="#集中式-vs-分布式" aria-label="Permalink to &quot;集中式 vs 分布式&quot;">​</a></h3><p>集中式通过<strong>向上扩展</strong>（Scale Up：加CPU/内存/磁盘）；分布式通过<strong>向外扩展</strong>（Scale Out：数据复制/切分/缓存）。</p><h3 id="图数据库适用场景" tabindex="-1">图数据库适用场景 <a class="header-anchor" href="#图数据库适用场景" aria-label="Permalink to &quot;图数据库适用场景&quot;">​</a></h3><p>知识图谱：适配复杂关系建模（多类型实体+多维关系）、高效图遍历查询、无模式特性支持动态扩展。</p><hr><h2 id="嵌入式系统补充" tabindex="-1">嵌入式系统补充 <a class="header-anchor" href="#嵌入式系统补充" aria-label="Permalink to &quot;嵌入式系统补充&quot;">​</a></h2><h3 id="ros2-四种通信模型" tabindex="-1">ROS2 四种通信模型 <a class="header-anchor" href="#ros2-四种通信模型" aria-label="Permalink to &quot;ROS2 四种通信模型&quot;">​</a></h3><table tabindex="0"><thead><tr><th>模型</th><th>特点</th></tr></thead><tbody><tr><td><strong>话题</strong></td><td>单向，发布→订阅</td></tr><tr><td><strong>服务</strong></td><td>请求→响应</td></tr><tr><td><strong>动作</strong></td><td>带连续反馈的请求→响应</td></tr><tr><td><strong>参数</strong></td><td>基于共享，服务端设数据，客户端操作</td></tr></tbody></table><h3 id="autosar" tabindex="-1">AUTOSAR <a class="header-anchor" href="#autosar" aria-label="Permalink to &quot;AUTOSAR&quot;">​</a></h3><p>支持多厂家汽车电子基础软件、软件重用、全生命周期覆盖。覆盖汽车电子三大领域：动力、底盘、车身。</p><hr><h2 id="安全补充" tabindex="-1">安全补充 <a class="header-anchor" href="#安全补充" aria-label="Permalink to &quot;安全补充&quot;">​</a></h2><h3 id="对称加密-vs-公钥加密流程" tabindex="-1">对称加密 vs 公钥加密流程 <a class="header-anchor" href="#对称加密-vs-公钥加密流程" aria-label="Permalink to &quot;对称加密 vs 公钥加密流程&quot;">​</a></h3><table tabindex="0"><thead><tr><th>操作</th><th>对称加密</th><th>公钥加密</th></tr></thead><tbody><tr><td><strong>机密性</strong></td><td>对称密钥加密，有相同密钥者解密</td><td>接收者公钥加密，对应私钥解密</td></tr><tr><td><strong>完整性</strong></td><td>生成MAC→对称密钥加密MAC</td><td>生成MAC→发送者私钥加密MAC→接收者用公钥解密对比</td></tr></tbody></table><h3 id="认证方式三类" tabindex="-1">认证方式三类 <a class="header-anchor" href="#认证方式三类" aria-label="Permalink to &quot;认证方式三类&quot;">​</a></h3><p>用户名口令（明文/散列/散列+随机数）+ 令牌（证书/智能卡）+ 生物识别（图像/指纹/气味/声音）。</p><h3 id="授权侵犯-vs-抗抵赖" tabindex="-1">授权侵犯 vs 抗抵赖 <a class="header-anchor" href="#授权侵犯-vs-抗抵赖" aria-label="Permalink to &quot;授权侵犯 vs 抗抵赖&quot;">​</a></h3><p>授权侵犯=被授权者将权限用于非授权目的（内部攻击）。抗抵赖=证据的生成/验证/记录，确认数据原发者身份和完整性。</p><hr><h2 id="新技术补充" tabindex="-1">新技术补充 <a class="header-anchor" href="#新技术补充" aria-label="Permalink to &quot;新技术补充&quot;">​</a></h2><h3 id="区块链六层" tabindex="-1">区块链六层 <a class="header-anchor" href="#区块链六层" aria-label="Permalink to &quot;区块链六层&quot;">​</a></h3><p>数据层→网络层→共识层→激励层→合约层→应用层。</p><h3 id="端侧ai-vs-云端ai" tabindex="-1">端侧AI vs 云端AI <a class="header-anchor" href="#端侧ai-vs-云端ai" aria-label="Permalink to &quot;端侧AI vs 云端AI&quot;">​</a></h3><table tabindex="0"><thead><tr><th>云端AI</th><th>端侧AI</th></tr></thead><tbody><tr><td>远程数据中心训练推理</td><td>终端设备直接推理</td></tr><tr><td>依赖网络传输</td><td><strong>低延迟、隐私保护、离线可用、省带宽</strong></td></tr></tbody></table><h3 id="集中式-vs-分布式-vs-混合云" tabindex="-1">集中式 vs 分布式 vs 混合云 <a class="header-anchor" href="#集中式-vs-分布式-vs-混合云" aria-label="Permalink to &quot;集中式 vs 分布式 vs 混合云&quot;">​</a></h3><p>集中式=单中心统一管理（单点风险）。分布式=多节点去中心化（横向扩展）。混合云=私有+公有统一管理调度。</p>',70)])])}const u=d(e,[["render",n]]);export{c as __pageData,u as default};
